const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update order status to cancelled
db.prepare(\"UPDATE orders SET status = 'cancelled', cancel_reason = 'customer_requested' WHERE order_id = 'ORD-E0E671'\").run();

// Update item statuses to cancelled
